//go:build ppc64le

package floats

import (
	"unsafe"

	"golang.org/x/sys/cpu"
)

// The ppc64le kernel of CMulTo (cmulto.go), generated by go-asmgen
// (cmulto_ppc64le_gen.go) into cmulto_ppc64le.s: VSX (the POWER8 baseline, as the other
// ppc64le kernels), one complex number per vector register, four per step and the last
// two and one in the same call. go:noescape.
//
//go:noescape
func cmulToVSX(dst, a, b *float64, n int)

// cmulToVSXMin is the length from which the kernel beats the portable loop on POWER8
// (measured in the pull request); below it the loop wins.
const cmulToVSXMin = 32

// cmulToVSXOn is the VSX gate (POWER8 and later). The first variant, one number per
// register, lost to the Go loop on POWER9 by 11 to 30 %; splitting two numbers into real
// and imaginary vectors (fewer permutes) wins on POWER9 and POWER8 alike.
var cmulToVSXOn = cpu.PPC64.IsPOWER8

func cmulTo(dst, a, b []complex128) {
	if cmulToVSXOn && len(dst) >= cmulToVSXMin {
		cmulToVSX(f64ptr(&dst[0]), f64ptr(&a[0]), f64ptr(&b[0]), len(dst))
		return
	}
	cmulToTail(dst, a, b, 0)
}

func f64ptr(p *complex128) *float64 { return (*float64)(unsafe.Pointer(p)) }
